  })[v] || '#f0f0f0';
  const gafPct = Math.round(form.gaf_score / 100 * 100);
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
  <title>Nota · ${form.patient_name || 'Paciente'} · ${form.enc_date || ''}</title>
  <style>
    @page { size: letter portrait; margin: 12mm 13mm 10mm; }
    *{ box-sizing:border-box; margin:0; padding:0; }
    body{ font-family:'Calibri',Arial,sans-serif; font-size:8.2pt; color:#1e2530; background:#fff; }

    /* HEADER */
    .hdr{ display:flex; align-items:center; justify-content:space-between; padding-bottom:7pt; margin-bottom:7pt; border-bottom:2pt solid #1a2c4e; }
    .hdr-left{ display:flex; align-items:center; gap:10pt; }
    .logo-circle{ width:32pt; height:32pt; border-radius:50%; background:#1a2c4e; display:flex; align-items:center; justify-content:center; color:#fff; font-size:10pt; font-weight:700; flex-shrink:0; }
    .clinic-name{ font-size:12pt; font-weight:700; color:#1a2c4e; line-height:1.2; }
    .clinic-sub{ font-size:7pt; color:#9aa3b2; letter-spacing:.05em; text-transform:uppercase; margin-top:1pt; }
    .hdr-right{ text-align:right; }
    .doc-type{ font-size:11pt; font-weight:700; color:#1D9E75; }
    .doc-meta{ font-size:7pt; color:#9aa3b2; margin-top:2pt; }
    .confidential{ display:inline-block; background:#FCEBEB; color:#A32D2D; font-size:6.5pt; font-weight:700; padding:1.5pt 6pt; border-radius:3pt; letter-spacing:.05em; text-transform:uppercase; margin-top:3pt; }

    /* PATIENT BANNER */
    .pt-banner{ background:#1a2c4e; color:#fff; border-radius:5pt; padding:6pt 10pt; margin-bottom:7pt; display:flex; align-items:center; justify-content:space-between; }
    .pt-name{ font-size:11pt; font-weight:700; letter-spacing:.01em; }
    .pt-meta{ font-size:7.5pt; color:#9ab0cc; margin-top:1.5pt; display:flex; gap:10pt; flex-wrap:wrap; }
    .pt-dx{ font-size:8pt; color:#9FE1CB; text-align:right; max-width:200pt; }

    /* GRID */
    .main-grid{ display:grid; grid-template-columns:1fr 1fr; gap:7pt; margin-bottom:6pt; }
    .full-width{ grid-column:span 2; }

    /* SECTION */
    .sec{ margin-bottom:5pt; }
    .sec-title{ font-size:7pt; font-weight:700; color:#1D9E75; text-transform:uppercase; letter-spacing:.07em; border-bottom:.5pt solid #1D9E75; padding-bottom:1.5pt; margin-bottom:3pt; display:flex; align-items:center; gap:4pt; }
    .sec-num{ background:#1D9E75; color:#fff; font-size:6pt; font-weight:700; width:10pt; height:10pt; border-radius:50%; display:inline-flex; align-items:center; justify-content:center; flex-shrink:0; }

    /* TABLES */
    table{ width:100%; border-collapse:collapse; }
    .rl{ width:36%; padding:2pt 5pt; font-weight:600; color:#1a2c4e; font-size:7.8pt; background:#f7f9fc; border:.3pt solid #dde3ec; vertical-align:top; }
    .rv{ padding:2pt 5pt; font-size:7.8pt; color:#2d3748; border:.3pt solid #dde3ec; vertical-align:top; }

    /* GAF */
    .gaf-box{ background:#f7f9fc; border:.3pt solid #dde3ec; border-radius:4pt; padding:5pt 8pt; display:flex; align-items:center; gap:10pt; }
    .gaf-score{ font-size:22pt; font-weight:700; color:#1a2c4e; line-height:1; }
    .gaf-lbl{ font-size:8pt; font-weight:600; color:#1D9E75; margin-top:1pt; }
    .gaf-bar-wrap{ flex:1; }
    .gaf-bar-bg{ background:#e2e6ec; border-radius:3pt; height:7pt; }
    .gaf-bar-fill{ height:7pt; border-radius:3pt; background:linear-gradient(to right,#E24B4A,#EF9F27 40%,#1D9E75 75%,#0F6E56); }
    .gaf-scale{ display:flex; justify-content:space-between; font-size:6pt; color:#9aa3b2; margin-top:2pt; }

    /* RISK */
    .risk-row{ display:flex; gap:5pt; }
    .risk-chip{ flex:1; text-align:center; padding:3pt 4pt; border-radius:3pt; font-size:7.5pt; font-weight:700; }

    /* TAGS */
    .tag-wrap{ display:flex; flex-wrap:wrap; gap:2.5pt; }
    .tag{ background:#E1F5EE; color:#0F6E56; border:.3pt solid #9FE1CB; padding:1.5pt 5pt; border-radius:3pt; font-size:7pt; font-weight:500; }
    .tag-blue{ background:#E6F1FB; color:#0C447C; border-color:#9FC5EE; }

    /* NARRATIVE */
    .narrative{ background:#f7f9fc; border:.3pt solid #dde3ec; border-radius:3pt; padding:4pt 6pt; font-size:7.8pt; line-height:1.5; color:#2d3748; }

    /* SIGNATURE */
    .sig-section{ background:#f7f9fc; border:.5pt solid #dde3ec; border-radius:5pt; padding:6pt 10pt; margin-bottom:5pt; display:grid; grid-template-columns:1fr 1fr; gap:12pt; }
    .sig-line{ border-bottom:1.5pt solid #1a2c4e; min-height:22pt; padding-bottom:2pt; font-size:9pt; font-weight:700; color:#1a2c4e; display:flex; align-items:flex-end; }
    .sig-lbl{ font-size:6.5pt; color:#9aa3b2; text-transform:uppercase; letter-spacing:.05em; margin-top:2pt; }

    /* CERT */
    .cert{ background:#E1F5EE; border:.5pt solid #9FE1CB; border-radius:4pt; padding:5pt 8pt; font-size:7.5pt; color:#0F6E56; line-height:1.5; margin-bottom:4pt; }
    .cert strong{ font-weight:700; }

    /* FOOTER */
    .footer{ text-align:center; font-size:6.5pt; color:#c8cdd6; padding-top:4pt; border-top:.3pt solid #e2e6ec; }

    @media print{
      *{ -webkit-print-color-adjust:exact!important; print-color-adjust:exact!important; }
      .pt-banner,.hdr,.sec-num{ -webkit-print-color-adjust:exact!important; }
    }
  </style>
  </head><body>

  <!-- HEADER -->
  <div class="hdr">
    <div class="hdr-left">
      <div class="logo-circle">CPC</div>
      <div>
        <div class="clinic-name">Caribbean Psychology Wellness Center</div>
        <div class="clinic-sub">San Juan, Puerto Rico &nbsp;·&nbsp; caribbeanpsychology.com</div>
      </div>
    </div>
    <div class="hdr-right">
      <div class="doc-type">Nota de Progreso Clínico</div>
      <div class="doc-meta">${form.enc_date || ''} &nbsp;·&nbsp; Sesión ${form.session_num || '—'} &nbsp;·&nbsp; ${form.session_type || ''} ${form.modality ? '· ' + form.modality : ''}</div>
      <div class="confidential">Confidencial · HIPAA · Ley 408 PR</div>
    </div>
