        ${form.record_num ? `<span>Exp: ${form.record_num}</span>` : ''}
        ${form.insurance ? `<span>${form.insurance}</span>` : ''}
        ${form.cpt_code ? `<span>CPT: ${form.cpt_code.split('–')[0].trim()}</span>` : ''}
      </div>
    </div>
    ${form.diagnosis ? `<div class="pt-dx">${form.diagnosis}</div>` : ''}
  </div>

  <!-- MAIN GRID -->
  <div class="main-grid">

    <!-- LEFT COLUMN -->
    <div>
      <!-- CLINICO -->
      <div class="sec">
        <div class="sec-title"><span class="sec-num">1</span> Datos del Encuentro</div>
        <table>${row('Clínico', form.clinician)}${row('Hora', form.time_start && form.time_end ? form.time_start + ' – ' + form.time_end + (form.duration_min ? ' (' + form.duration_min + ' min)' : '') : '')}</table>
      </div>

      <!-- MSE -->
      <div class="sec">
        <div class="sec-title"><span class="sec-num">3</span> Estado Mental (MSE)</div>
        <table>
          ${row('Apariencia', arr(form.apariencia))}
          ${row('Actitud', arr(form.actitud))}
          ${val(form.mood) ? `<tr><td class="rl">Ánimo (autoreportado)</td><td class="rv"><em>"${form.mood}"</em></td></tr>` : ''}
          ${row('Afecto observado', form.afecto)}
          ${row('Pensamiento', arr(form.pensamiento))}
          ${row('Orientación/Insight', arr(form.orientacion))}
        </table>
        ${val(form.mse_notes) ? `<div class="narrative" style="margin-top:3pt">${form.mse_notes}</div>` : ''}
      </div>

      <!-- GAF -->
      <div class="sec">
        <div class="sec-title"><span class="sec-num">4</span> Funcionalidad Global (GAF)</div>
        <div class="gaf-box">
          <div>
            <div class="gaf-score">${form.gaf_score}</div>
            <div class="gaf-lbl">${gLabel(form.gaf_score)}</div>
          </div>
          <div class="gaf-bar-wrap">
            <div class="gaf-bar-bg"><div class="gaf-bar-fill" style="width:${gafPct}%"></div></div>
            <div class="gaf-scale"><span>1</span><span>25</span><span>50</span><span>75</span><span>100</span></div>
          </div>
        </div>
      </div>

      <!-- RISK -->
      <div class="sec">
        <div class="sec-title"><span class="sec-num">5</span> Evaluación de Riesgo</div>
        <div class="risk-row">
          <div class="risk-chip" style="background:${riskBg(form.risk_suicida)};color:${riskColor(form.risk_suicida)}">
            <div style="font-size:6pt;font-weight:400;margin-bottom:1pt">SUICIDA</div>
            ${form.risk_suicida || '—'}
          </div>
          <div class="risk-chip" style="background:${riskBg(form.risk_homicida)};color:${riskColor(form.risk_homicida)}">
            <div style="font-size:6pt;font-weight:400;margin-bottom:1pt">HOMICIDA</div>
            ${form.risk_homicida || '—'}
          </div>
        </div>
        ${val(form.safety_plan) ? `<div class="narrative" style="margin-top:3pt">${form.safety_plan}</div>` : ''}
      </div>
    </div>

    <!-- RIGHT COLUMN -->
    <div>
      <!-- INTERVENCIONES -->
      <div class="sec">
        <div class="sec-title"><span class="sec-num">6</span> Contenido e Intervenciones</div>
        ${val(form.session_topics) ? `<div class="narrative" style="margin-bottom:3pt">${form.session_topics}</div>` : ''}
        ${arr(form.tecnicas) ? `<div class="tag-wrap" style="margin-bottom:3pt">${arr(form.tecnicas).split(' · ').map(t => `<span class="tag">${t}</span>`).join('')}</div>` : ''}
        ${val(form.resp_interv) ? `<div class="narrative">${form.resp_interv}</div>` : ''}
      </div>

      <!-- PROGRESO -->
      <div class="sec">
        <div class="sec-title"><span class="sec-num">7</span> Progreso y Plan</div>
        ${val(form.progreso) ? `<div style="margin-bottom:3pt"><span class="tag tag-blue">${form.progreso}</span></div>` : ''}
        ${arr(form.cambios) ? `<div class="tag-wrap" style="margin-bottom:3pt">${arr(form.cambios).split(' · ').map(t => `<span class="tag">${t}</span>`).join('')}</div>` : ''}
        ${val(form.homework) ? `<div class="narrative" style="margin-bottom:3pt">${form.homework}</div>` : ''}
        <table>
          ${row('Próxima cita', form.next_appt)}
          ${row('Frecuencia', form.frequency)}
        </table>
      </div>

      ${val(form.extra_notes) ? `
      <div class="sec">
        <div class="sec-title"><span class="sec-num">8</span> Notas Adicionales</div>
        <div class="narrative">${form.extra_notes}</div>
      </div>` : ''}
    </div>

  </div><!-- end main-grid -->

  <!-- FIRMA -->
  <div class="sec-title" style="margin-bottom:4pt"><span class="sec-num">9</span> Certificación y Firma Electrónica</div>
  <div class="sig-section">
    <div>
      <div class="sig-line">${form.signed_by || form.clinician || '—'}</div>
      <div class="sig-lbl">Clínico responsable · Nombre · Credencial · Licencia</div>
    </div>
    <div>
      <div class="sig-line">${form.signed_at ? new Date(form.signed_at).toLocaleString('es-PR', {
    dateStyle: 'short',
    timeStyle: 'short'
  }) : '—'}</div>
      <div class="sig-lbl">Fecha y hora de firma electrónica · Puerto Rico</div>
    </div>
  </div>
  <div class="cert"><strong>Certificación:</strong> El clínico firmante certifica que la información contenida en esta nota de progreso es correcta, completa y fue documentada de forma contemporánea al servicio, en cumplimiento con HIPAA, la Ley Núm. 408 de Puerto Rico y los estándares éticos de la práctica psicológica.</div>
  <div class="footer">Caribbean Psychology Wellness Center &nbsp;·&nbsp; Nota de Progreso Clínico &nbsp;·&nbsp; Confidencial – HIPAA &nbsp;·&nbsp; ${new Date().toLocaleDateString('es-PR')}</div>

  </body></html>`;
}
